	c.Request.ExpectedFingerprint = fingerprint
	return c, nil
}

func validateQAOperationRequest(req OperationRequest) error {
	switch req.Kind {
	case OperationQAStatus, OperationQADryRun, OperationQAStart, OperationQAResume, OperationQARecover:
	default:
