package main

import (
	"database/sql"
	"fmt"
	"sync"
	"time"

	_ "modernc.org/sqlite"
)

func main() {
	db1, err := sql.Open("sqlite", "file:/tmp/opencode/rcprobe/t1.db?_busy_timeout=5000&_txlock=immediate&_journal_mode=WAL")
	if err != nil {
		panic(err)
	}
	defer db1.Close()
	db1.SetMaxOpenConns(1)
	db2, err := sql.Open("sqlite", "file:/tmp/opencode/rcprobe/t1.db?_busy_timeout=200&_txlock=immediate&_journal_mode=WAL")
	if err != nil {
		panic(err)
	}
	defer db2.Close()
	db2.SetMaxOpenConns(1)
	if _, err := db1.Exec(`CREATE TABLE IF NOT EXISTS t (a INTEGER)`); err != nil {
		panic(err)
	}

	tx1, err := db1.Begin()
	if err != nil {
		panic(err)
	}
	// tx1 takes the immediate write lock at BEGIN even though it only reads.
	var one int
	if err := tx1.QueryRow(`SELECT 1`).Scan(&one); err != nil {
		panic(err)
	}
	done := make(chan error, 1)
	go func() {
		tx2, err := db2.Begin() // immediate: must contend NOW, at begin/read time
		if err != nil {
			done <- err
			return
		}
		if _, err := tx2.Exec(`INSERT INTO t VALUES (2)`); err != nil {
			done <- err
			return
		}
		tx2.Commit()
		done <- nil
	}()
	select {
	case err := <-done:
		fmt.Println("second immediate txn during first's read-only txn:", err)
	case <-time.After(3 * time.Second):
		fmt.Println("second txn blocked >3s (immediate contention confirmed)")
	}
	tx1.Rollback()
	fmt.Println("after release:", <-done)

	// deferred control: without _txlock=immediate the reader txn above would NOT block a writer
	var wg sync.WaitGroup
	wg.Add(1)
	go func() { defer wg.Done(); _ = one }()
}
EOF
go run . 2>&1

