func TestZZQuotaGateBypassViaOversizeSanitizeStub(t *testing.T) {
	ctx := context.Background()
	root := t.TempDir()
	repository, err := OpenSQLite(ctx, root, SQLiteOptions{})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = repository.Close() })
	runID, fence := acceptedClaimedRun(t, repository)

	pad := filepath.Join(root, ".ultraplan", "run-control.db.pad")
	file, err := os.Create(pad)
	if err != nil {
		t.Fatal(err)
	}
	if err := file.Truncate(DefaultHardQuotaBytes); err != nil {
		t.Fatal(err)
	}
	if err := file.Close(); err != nil {
		t.Fatal(err)
	}

	usage, err := repository.storageBytes()
	if err != nil {
		t.Fatal(err)
