package runcontrol

import (
	"context"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestZZQuotaGateBypassViaOversizeSanitizeStub(t *testing.T) {
	ctx := context.Background()
	root := t.TempDir()
	repository, err := OpenSQLite(ctx, root, SQLiteOptions{})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = repository.Close() })
	runID, fence := acceptedClaimedRun(t, repository)

	pad := filepath.Join(root, ".ultraplan", "run-control.db.pad")
	file, err := os.Create(pad)
	if err != nil {
		t.Fatal(err)
	}
	if err := file.Truncate(DefaultHardQuotaBytes); err != nil {
		t.Fatal(err)
	}
	if err := file.Close(); err != nil {
		t.Fatal(err)
	}
	usage, err := repository.storageBytes()
	if err != nil || usage < DefaultHardQuotaBytes {
		t.Fatalf("pad failed: usage=%d err=%v", usage, err)
	}

	if _, _, err := repository.Append(ctx, fence, EventDraft{Type: EventProgress, Payload: map[string]string{"message": "small"}}); !errors.Is(err, ErrQuota) {
		t.Fatalf("control small non-reserved append at hard quota: err=%v, want ErrQuota", err)
	}

	huge := map[string]string{}
	for _, k := range []string{"message", "summary", "detail", "reason", "state"} {
		huge[k] = strings.Repeat("x", 32_000)
	}
	event, _, err := repository.Append(ctx, fence, EventDraft{Type: EventProgress, Payload: huge})
	if err != nil {
		t.Fatalf("oversize append at hard quota: err=%v", err)
	}
	if event.Type != EventWarning {
		t.Fatalf("bypassed event type=%v, want rewritten warning stub", event.Type)
	}
	events, err := repository.Events(ctx, runID, 0, 10)
	if err != nil {
		t.Fatal(err)
	}
	var payloadKeys int
	for _, e := range events {
		if e.Sequence == event.Sequence {
			payloadKeys = len(e.Payload)
		}
	}
	t.Logf("RESULT: oversize progress admitted at hard-quota as %s seq=%d persistedPayloadKeys=%d (stub)", event.Type, event.Sequence, payloadKeys)
}

func TestZZAliasPermanentlyBoundToTerminalRun(t *testing.T) {
	ctx := context.Background()
	repository := openTestRepository(t, t.TempDir())
	defer repository.Close()
	snapshot, err := repository.Accept(ctx, Acceptance{Target: Target{Kind: "sprint", Operation: "execute"}, OperationAlias: "tui-stable-digest"})
	if err != nil {
		t.Fatal(err)
	}
	now := formatTime(repository.now())
	if _, err := repository.db.Exec(`UPDATE runs SET lifecycle='interrupted', liveness='terminal', started_at=?, finished_at=?, updated_at=?, terminal_outcome='interrupted', terminal_at=?, terminal_reason='owner_never_claimed_after_grace', terminal_proposed_by='reconciler' WHERE run_id=?`,
		now, now, now, now, string(snapshot.RunID)); err != nil {
		t.Fatal(err)
	}
	dead, err := repository.Snapshot(ctx, snapshot.RunID)
	if err != nil || dead.Lifecycle != LifecycleInterrupted || dead.Terminal == nil {
		t.Fatalf("terminal setup: %+v err=%v", dead, err)
	}
	if _, err := repository.Accept(ctx, Acceptance{Target: Target{Kind: "sprint", Operation: "execute"}, OperationAlias: "tui-stable-digest"}); !errors.Is(err, ErrConflict) {
		t.Fatalf("retry accept err=%v, want conflict", err)
	}
	resolved, err := repository.ResolveOperationAlias(ctx, "tui-stable-digest")
	if err != nil {
		t.Fatal(err)
	}
	if resolved.RunID != snapshot.RunID || resolved.Terminal == nil {
		t.Fatalf("resolved=%+v, want dead original run handed back as dedup hit", resolved)
	}
	t.Logf("RESULT: stable digest resolves to terminal (%s) run %s; insert-only alias, no rebind/expiry API exists", resolved.Lifecycle, resolved.RunID)
}
EOF
