	if _, err := repository.db.Exec(`UPDATE runs SET lifecycle='interrupted', liveness='terminal', started_at=?, finished_at=?, updated_at=?, terminal_outcome='interrupted', terminal_at=?, terminal_reason='owner_never_claimed_after_grace', terminal_proposed_by='reconciler' WHERE run_id=?`,
		now, now, now, now, string(snapshot.RunID)); err != nil {
		t.Fatal(err)
	}
	dead, err := repository.Snapshot(ctx, snapshot.RunID)
	if err != nil || dead.Lifecycle != LifecycleInterrupted || dead.Terminal == nil {
		t.Fatalf("terminal setup: %+v err=%v", dead, err)
	}
	if _, err := repository.Accept(ctx, Acceptance{Target: Target{Kind: "sprint", Operation: "execute"}, OperationAlias: "tui-stable-digest"}); !errors.Is(err, ErrConflict) {
		t.Fatalf("retry accept err=%v, want conflict", err)
	}
	resolved, err := repository.ResolveOperationAlias(ctx, "tui-stable-digest")
	if err != nil {
		t.Fatal(err)
	}
	if resolved.RunID != snapshot.RunID || resolved.Terminal == nil {
		t.Fatalf("resolved=%+v, want dead original run handed back as dedup hit", resolved)
	}
	t.Logf("RESULT: stable digest resolves to terminal (%s) run %s; insert-only alias, no rebind/expiry API exists", resolved.Lifecycle, resolved.RunID)
}
